import numpy as np
from model import coefficients

def q(nu,k,w):
 p,c=coefficients(nu,k,w); ep=.75*nu/(1-1j*w);u=-p*c;v=-1j*k*c;up=p*p*c;vp=1j*k*p*c;axx=1j*k*u;axy=up;ayx=1j*k*v;txx=ep*2j*k*u;tyy=ep*2*vp;txy=ep*(up+1j*k*v);d=p[:,None]+p.conj()[None,:]
 return .5*np.real(np.sum((u[:,None]*(1j*k*txy).conj()[None,:]+v[:,None]*(-p*txy).conj()[None,:]-axy[:,None]*tyy.conj()[None,:]-txx[:,None]*ayx.conj()[None,:])/d))
for nu in [10,100,1000,1e6]: print(nu,q(nu,.7,.5)/nu)
PY"
